import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadArchitectsDaughter = makeLoadFont('ArchitectsDaughter');
const loadCaveat = makeLoadFont('Caveat');
import { evolvePath } from "@remotion/paths";

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: architectsDaughterFamily } = loadArchitectsDaughter();
const { fontFamily: caveatFamily } = loadCaveat();

interface Point {
  x: number;
  y: number;
}

const getCubicBezierPoint = (p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point => {
  const mt = 1 - t;
  return {
    x: mt * mt * mt * p0.x + 3 * mt * mt * t * p1.x + 3 * mt * t * t * p2.x + t * t * t * p3.x,
    y: mt * mt * mt * p0.y + 3 * mt * mt * t * p1.y + 3 * mt * t * t * p2.y + t * t * t * p3.y,
  };
};

const getCubicBezierTangent = (p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point => {
  const mt = 1 - t;
  return {
    x: 3 * mt * mt * (p1.x - p0.x) + 6 * mt * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x),
    y: 3 * mt * mt * (p1.y - p0.y) + 6 * mt * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y),
  };
};

const getCirclePath = (cx: number, cy: number, r: number) => {
  return `M ${cx} ${cy - r} A ${r} ${r} 0 1 1 ${cx - 0.1} ${cy - r}`;
};



export type FlywheelDiagramProps = Record<string, any>;

interface ArrowProps {
  p0: Point;
  p1: Point;
  p2: Point;
  p3: Point;
  progress: number;
  color: string;
  strokeWidth: number;
  filterId: string;
}

const Arrow: React.FC<ArrowProps> = ({
  p0,
  p1,
  p2,
  p3,
  progress,
  color,
  strokeWidth,
  filterId,
}) => {
  const pathData = `M ${p0.x} ${p0.y} C ${p1.x} ${p1.y}, ${p2.x} ${p2.y}, ${p3.x} ${p3.y}`;
  const evolution = evolvePath(progress, pathData);

  const point = getCubicBezierPoint(p0, p1, p2, p3, progress);
  const tangent = getCubicBezierTangent(p0, p1, p2, p3, progress);
  const angle = Math.atan2(tangent.y, tangent.x);
  const angleDeg = (angle * 180) / Math.PI;

  return (
    <g style={{ filter: `url(#${filterId})` }}>
      <path
        d={pathData}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={evolution.strokeDasharray}
        strokeDashoffset={evolution.strokeDashoffset}
        style={{ transition: "none" }}
      />
      {progress > 0.05 && (
        <path
          d="M -16 -10 C -12 -4, -4 -2, 4 0 C -4 2, -12 4, -16 10 C -14 3, -14 -3, -16 -10 Z"
          fill={color}
          style={{
            transform: `translate(${point.x}px, ${point.y}px) rotate(${angleDeg}deg)`,
            transformOrigin: "center",
            transition: "none",
          }}
        />
      )}
    </g>
  );
};

const FlywheelDiagram: React.FC<FlywheelDiagramProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 12,
  circleColor = "#ffa000",
  circleStrokeColor = "#ffffff",
  arrowColor = "#ffffff",
  textColor = "#ffffff",
  growthTextColor = "#000000",
  strokeWidth = 5,
  textWiggleIntensity = 2.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Animation timeline configuration (scaled to duration)
  const totalFrames = durationInSeconds * fps;
  const scaleFrame = (f: number) => {
    return Math.round((f / 320) * totalFrames);
  };

  // Safe Background color parser
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive layouts
  const baseSize = Math.min(width, height);
  const fontSizeMultiplier = baseSize / 1080;
  const cx = width / 2;
  const cy = height / 2 + 80 * fontSizeMultiplier; // Shift down slightly for top labels
  const circleRadius = 150 * fontSizeMultiplier;

  // Camera Hand-held wiggle logic (using deterministic trigonometric noise)
  const cameraWiggleX = interpolate(
    Math.sin(frame * 0.4),
    [-1, 1],
    [-1.5, 1.5]
  ) * textWiggleIntensity;

  const cameraWiggleY = interpolate(
    Math.cos(frame * 0.35),
    [-1, 1],
    [-1.2, 1.2]
  ) * textWiggleIntensity;

  // Stop-motion whiteboard frame rate wiggle seed
  const wiggleFrame = Math.floor(frame / 3);
  const noiseSeed = (wiggleFrame % 10) * 7.31;

  // Central circle outline draw
  const circleStart = scaleFrame(265);
  const circleEnd = scaleFrame(295);
  const circleDrawProgress = interpolate(
    frame,
    [circleStart, circleEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const fillStart = scaleFrame(285);
  const fillEnd = scaleFrame(310);
  const fillOpacity = interpolate(
    frame,
    [fillStart, fillEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Central circle geometry
  const circlePath = getCirclePath(cx, cy, circleRadius);
  const circleEvolution = evolvePath(circleDrawProgress, circlePath);

  // GROWTH text scale/spring
  const growthStart = scaleFrame(300);
  const growthSpring = spring({
    frame: frame - growthStart,
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  const growthTextSpring = interpolate(growthSpring, [0, 1], [0.5, 1.0]);
  const growthTextRotate = interpolate(growthSpring, [0, 1], [-10, 0.5]);
  const growthTextOpacity = interpolate(growthSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
  });

  // Coordinates Scale Helper (Coordinates mapped relative to 1920x1080 design)
  const scalePoint = (x: number, y: number) => ({
    x: (x / 1920) * width,
    y: (y / 1080) * height,
  });

  // Clockwise connecting arrows configuration in custom order
  const arrows = [
    {
      id: "selection-to-experience",
      p0: scalePoint(1090, 380),
      p1: scalePoint(1200, 380),
      p2: scalePoint(1310, 470),
      p3: scalePoint(1310, 570),
      startFrame: 25,
      endFrame: 45,
    },
    {
      id: "experience-to-traffic",
      p0: scalePoint(1310, 710),
      p1: scalePoint(1310, 810),
      p2: scalePoint(1200, 920),
      p3: scalePoint(1090, 920),
      startFrame: 60,
      endFrame: 80,
    },
    {
      id: "traffic-to-sellers",
      p0: scalePoint(830, 920),
      p1: scalePoint(720, 920),
      p2: scalePoint(610, 810),
      p3: scalePoint(610, 710),
      startFrame: 95,
      endFrame: 115,
    },
    {
      id: "sellers-to-selection",
      p0: scalePoint(610, 570),
      p1: scalePoint(610, 470),
      p2: scalePoint(720, 380),
      p3: scalePoint(830, 380),
      startFrame: 130,
      endFrame: 150,
    },
    {
      id: "sellers-to-lower-cost",
      p0: scalePoint(540, 500),
      p1: scalePoint(430, 350),
      p2: scalePoint(430, 240),
      p3: scalePoint(560, 180),
      startFrame: 155,
      endFrame: 180,
    },
    {
      id: "lower-cost-to-lower-prices",
      p0: scalePoint(880, 140),
      p1: scalePoint(950, 125),
      p2: scalePoint(1010, 125),
      p3: scalePoint(1080, 140),
      startFrame: 195,
      endFrame: 220,
    },
    {
      id: "lower-prices-to-experience",
      p0: scalePoint(1220, 180),
      p1: scalePoint(1350, 240),
      p2: scalePoint(1390, 350),
      p3: scalePoint(1350, 450),
      startFrame: 235,
      endFrame: 260,
    },
  ];

  // Handwritten labels configuration in custom order
  const labels = [
    {
      id: "selection",
      text: "SELECTION",
      pos: scalePoint(960, 380),
      activeFrame: 10,
    },
    {
      id: "experience",
      text: "CUSTOMER\nEXPERIENCE",
      pos: scalePoint(1310, 640),
      activeFrame: 45,
    },
    {
      id: "traffic",
      text: "TRAFFIC",
      pos: scalePoint(960, 920),
      activeFrame: 80,
    },
    {
      id: "sellers",
      text: "SELLERS",
      pos: scalePoint(610, 640),
      activeFrame: 115,
    },
    {
      id: "lower-cost",
      text: "LOWER COST\nSTRUCTURE",
      pos: scalePoint(710, 150),
      activeFrame: 180,
    },
    {
      id: "lower-prices",
      text: "LOWER\nPRICES",
      pos: scalePoint(1210, 150),
      activeFrame: 220,
    },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          position: "relative",
          overflow: "hidden",
          transform: `translate(${cameraWiggleX}px, ${cameraWiggleY}px)`,
          transition: "none",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            pointerEvents: "none",
          }}
        >
          {/* Custom felt-tip sketch filters definition */}
          <defs>
            <filter id="sketch-filter-strong" x="-20%" y="-20%" width="140%" height="140%">
              <feTurbulence
                type="fractalNoise"
                baseFrequency="0.015"
                numOctaves="3"
                result="noise"
                seed={noiseSeed}
              />
              <feDisplacementMap
                in="SourceGraphic"
                in2="noise"
                scale={10}
                xChannelSelector="R"
                yChannelSelector="G"
              />
            </filter>
            <filter id="sketch-filter-weak" x="-20%" y="-20%" width="140%" height="140%">
              <feTurbulence
                type="fractalNoise"
                baseFrequency="0.025"
                numOctaves="2"
                result="noise"
                seed={noiseSeed + 1.23}
              />
              <feDisplacementMap
                in="SourceGraphic"
                in2="noise"
                scale={5}
                xChannelSelector="R"
                yChannelSelector="G"
              />
            </filter>
          </defs>

          {/* Core Central Circle - Fill */}
          <path
            d={circlePath}
            fill={circleColor}
            stroke="none"
            style={{
              opacity: fillOpacity,
              filter: "url(#sketch-filter-strong)",
              transition: "none",
            }}
          />

          {/* Core Central Circle - Hand-drawn Outline */}
          <path
            d={circlePath}
            fill="none"
            stroke={circleStrokeColor}
            strokeWidth={strokeWidth + 2}
            strokeLinecap="round"
            strokeDasharray={circleEvolution.strokeDasharray}
            strokeDashoffset={circleEvolution.strokeDashoffset}
            style={{
              filter: "url(#sketch-filter-strong)",
              transition: "none",
            }}
          />

          {/* Animated Connecting Arrows */}
          {arrows.map((arrow) => {
            const progress = interpolate(
              frame,
              [scaleFrame(arrow.startFrame), scaleFrame(arrow.endFrame)],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            return (
              <Arrow
                key={arrow.id}
                p0={arrow.p0}
                p1={arrow.p1}
                p2={arrow.p2}
                p3={arrow.p3}
                progress={progress}
                color={arrowColor}
                strokeWidth={strokeWidth}
                filterId="sketch-filter-strong"
              />
            );
          })}
        </svg>

        {/* Central Core TEXT: GROWTH */}
        {growthTextOpacity > 0 && (
          <div
            style={{
              position: "absolute",
              left: `${(cx / width) * 100}%`,
              top: `${(cy / height) * 100}%`,
              transform: `translate(-50%, -50%) scale(${growthTextSpring}) rotate(${growthTextRotate}deg)`,
              opacity: growthTextOpacity,
              color: growthTextColor,
              fontFamily: architectsDaughterFamily,
              fontSize: `${54 * fontSizeMultiplier}px`,
              fontWeight: "bold",
              textAlign: "center",
              userSelect: "none",
              pointerEvents: "none",
              filter: "url(#sketch-filter-weak)",
              transition: "none",
            }}
          >
            GROWTH
          </div>
        )}

        {/* Hand-written Interactive Nodes */}
        {labels.map((lbl) => {
          const scaledActiveFrame = scaleFrame(lbl.activeFrame);
          if (frame < scaledActiveFrame) return null;

          const labelProgress = spring({
            frame: frame - scaledActiveFrame,
            fps,
            config: { damping: 14, stiffness: 120 },
          });

          const scale = interpolate(labelProgress, [0, 1], [0.6, 1.0]);
          const opacity = interpolate(labelProgress, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
          });

          // Natural wobbly orientation values to preserve blackboard aesthetic
          const naturalRotations: Record<string, number> = {
            "SELLERS": 2,
            "SELECTION": -1.5,
            "CUSTOMER\nEXPERIENCE": 1,
            "TRAFFIC": -1,
            "LOWER COST\nSTRUCTURE": -2.5,
            "LOWER\nPRICES": 1.5,
          };

          const baseRot = naturalRotations[lbl.text] || 0;
          const rotation = interpolate(labelProgress, [0, 1], [-8, baseRot]);

          return (
            <div
              key={lbl.id}
              style={{
                position: "absolute",
                left: `${(lbl.pos.x / width) * 100}%`,
                top: `${(lbl.pos.y / height) * 100}%`,
                transform: `translate(-50%, -50%) scale(${scale}) rotate(${rotation}deg)`,
                opacity,
                color: textColor,
                fontFamily: architectsDaughterFamily,
                fontSize: `${36 * fontSizeMultiplier}px`,
                fontWeight: "bold",
                textAlign: "center",
                lineHeight: 1.1,
                whiteSpace: "pre-line",
                userSelect: "none",
                pointerEvents: "none",
                filter: "url(#sketch-filter-weak)",
                transition: "none",
              }}
            >
              {lbl.text}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default FlywheelDiagram;